def min_Ops(arr, n, k):
    if k == 1:
        return 0
    unique_elements = set(arr)
    if len(unique_elements) == 1:
        return 0
    if len(unique_elements) > k:
        return -1
    max_freq = 0
    for num in unique_elements:
        freq = sum(1 for x in arr if x == num)
        max_freq = max(max_freq, freq)
    if len(unique_elements) - 1 > max_freq:
        return -1
    return sum(len(arr) - freq for freq in [sum(1 for x in arr if x == num) for num in unique_elements])
```

