def count_binary_seq(n):
    from math import factorial

    def comb(n, k):
        return factorial(n) // (factorial(k) * factorial(n - k))

    result = 0
    for i in range(n + 1):
        result += comb(n, i) ** 2
    return result * 2 ** (-n)
