def flip(arr, k):
    arr[:k] = arr[:k][::-1]

def find_max_index(arr, n):
    max_index = 0
    for i in range(n):
        if arr[i] > arr[max_index]:
            max_index = i
    return max_index

def pancake_sort(arr):
    cur_size = len(arr)
    while cur_size > 0:
        max_index = find_max_index(arr, cur_size)
        if max_index != cur_size - 1:
            if max_index != 0:
                flip(arr, max_index + 1)
            flip(arr, cur_size)
        cur_size -= 1
    return arr
```

