def find_ways(n):
    if n == 0:
        return 1
    dp = [1] + [0] * n
    for v in [1, -1]:
        temp = [0] * (n + 1)
        for i in range(n + 1):
            temp[i] += dp[i]
            if i - v >= 0:
                temp[i] += dp[i - v]
            if temp[i] > 0 and i >= v:
                temp[i] += temp[i - v]
        dp = temp
    return dp[n]
```

