def rearange_string(s):
    if len(s) <= 1:
        return s
    chars = sorted([(s.count(c), c) for c in set(s)], reverse=True)
    char_freqs = sorted([(f, c) for c, f in chars], reverse=True)
    odd_char = None
    if len(char_freqs) > 1 and char_freqs[1][0] == char_freqs[0][0] - 1:
        odd_char = char_freqs.pop(1)[1]
    res = [''] * len(s)
    index = 0
    for freq, char in char_freqs:
        for _ in range(freq):
            if index >= len(s):
                index = 1
            res[index] = char
            index += 2
    if odd_char:
        res[res.index('')] = odd_char
    return ''.join(res)
```

