def get_Min_Squares(n):
    if n <= 3:
        return n
    dp = [float('inf')] * (n + 1)
    dp[0], dp[1], dp[2], dp[3] = 0, 1, 2, 3
    for i in range(4, n + 1):
        for j in range(1, int(i ** 0.5) + 1):
            square = j * j
            dp[i] = min(dp[i], dp[i - square] + 1)
    return dp[n]
