def pancake_sort(arr):
    def flip(sub_arr, k):
        sub_arr[:k] = sub_arr[:k][::-1]

    n = len(arr)
    for size in range(n, 1, -1):
        max_index = max(range(size), key=arr.__getitem__)
        if max_index + 1 != size:
            if max_index != 0:
                flip(arr, max_index + 1)
            flip(arr, size)
    return arr
