import heapq

def func(nums, k):
    freq = {}
    for num_list in nums:
        for num in num_list:
            freq[num] = freq.get(num, 0) + 1

    heap = []
    for num, count in freq.items():
        heapq.heappush(heap, (count, num))
        if len(heap) > k:
            heapq.heappop(heap)

    result = []
    while heap:
        result.append(heapq.heappop(heap)[1])
    return result[::-1]
