    for i in range(len(digits) - 1, 0, -1):
        if digits[i] > digits[i - 1]:
            pivot = i - 1
            for j in range(i, len(digits)):
                if digits[j] > digits[pivot] and digits[j] < digits[i]:
                    replace = j
            digits[i - 1], digits[replace] = digits[replace], digits[i - 1]
            return int(''.join(digits[:i] + sorted(digits[i:])))

