def find_ways(n):
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for _ in range(1, n + 1):
        new_dp = [0] * (n + 1)
        for i in range(n + 1):
            if i >= 1:
                new_dp[i] += dp[i - 1]
            if i >= 2:
                new_dp[i] += dp[i - 2]
            if i >= 3:
                new_dp[i] += dp[i - 3]
        dp = new_dp
    return dp[n]
