def sumofFactors(n):
    if n % 2 != 0:
        n *= 2
    sum_factors = 0
    for i in range(2, int(n**0.5) + 1):
        count = 0
        current_sum = 1
        while n % i == 0:
            count += 1
            n //= i
            current_sum *= i
        if count > 0:
            sum_factors += current_sum
        if n == 1:
            break
    if n > 2:
        sum_factors += 2 * n
    return sum_factors * 2 if sum_factors else 2
