def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def generate_fibonacci_primes():
        a, b = 0, 1
        count = 0
        while True:
            fib_num = a
            a, b = b, a + b
            if is_prime(fib_num):
                count += 1
                if count == 1:
                    yield fib_num
                if count == n:
                    return fib_num

    return generate_fibonacci_primes().__next__()
```

