def magic_square_test(square):
    n = len(square)
    if n == 0:
        return False

    magic_sum = sum(square[0])

    # Check rows and columns
    for i in range(n):
        if sum(square[i]) != magic_sum or sum(row[i] for row in square) != magic_sum:
            return False

    # Check diagonals
    if sum(square[i][i] for i in range(n)) != magic_sum or sum(square[i][n - 1 - i] for i in range(n)) != magic_sum:
        return False

    # Check for unique numbers from 1 to n^2
    numbers = set(range(1, n * n + 1))
    if set(sum(row) for row in square) != numbers:
        return False

    return True
