def no_of_subsequences(arr, k):
    from collections import defaultdict

    def count_subsequences(index, product):
        if index == len(arr):
            return 1 if product < k else 0
        count = 0
        if product == 0:
            count += 1
        for i in range(index, len(arr)):
            product *= arr[i]
            count += 1 + count_subsequences(i + 1, product)
            if product >= k:
                break
        return count

    return count_subsequences(0, 1)
```

