def no_of_subsequences(arr, k):
    from math import log2, ceil
    from bisect import bisect_left

    def count_subsequences(prefix_log, current_log):
        count = 0
        while count_subsequences_cache[current_log] < len(prefix_log):
            current_log += 1
        return bisect_left(prefix_log, current_log) + 1

    prefix_log = [log2(arr[0])]
    for num in arr[1:]:
        prefix_log.append(prefix_log[-1] + log2(num))

    prefix_log.sort()
    count_subsequences_cache = [0] + [ceil(log2(num)) for num in prefix_log]

    total_subsequences = 0
    for log_val in prefix_log:
        if log_val < log2(k):
            total_subsequences += count_subsequences(prefix_log, log_val)

    return total_subsequences
