        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, 101) if is_prime(i)]
    prime_combinations = []

    for i in primes:
        for j in primes:
            for k in primes:
                product = i * j * k
                if product > a:
                    break
                prime_combinations.append(product)

    return a in prime_combinations
