def pancake_sort(arr):
    def flip(sub_arr, k):
        sub_arr[:k] = sub_arr[:k][::-1]

    n = len(arr)
    while n > 0:
        max_index = 0
        for i in range(n):
            if arr[i] > arr[max_index]:
                max_index = i
        if max_index != n - 1:
            if max_index != 0:
                flip(arr, max_index + 1)
            flip(arr, n)
        n -= 1
    return arr
```

