def replace_max_specialchar(text, n):
    special_chars = ' ,.'
    count = 0
    result = []
    temp = []
    for char in text:
        if char in special_chars:
            temp.append(char)
            count += 1
            if count <= n:
                result.append(':')
            else:
                result.append(char)
        else:
            result.extend(temp)
            temp = []
            count = 0
            result.append(char)
    result.extend(temp)
    return ''.join(result)
