def binomial_Coeff(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    C = [0 for _ in range(k+1)]
    C[0] = 1
    for i in range(1, n+1):
        for j in range(min(i, k), 0, -1):
            C[j] = C[j] + C[j-1]
    return C[k]
```

```python
def rearrange_bigger(n):
    digits = list(str(n))
    length = len(digits)

    i = length - 2
    while i >= 0 and digits[i] >= digits[i + 1]:
        i -= 1

    if i == -1:
        return False

    j = length - 1
    while digits[j] <= digits[i]:
        j -= 1

    digits[i], digits[j] = digits[j], digits[i]

    digits[i + 1:] = sorted(digits[i + 1:])

    return int(''.join(digits))
```

```python
def find_ways(n):
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for _ in range(1, n + 1):
        new_dp = [0] * (n + 1)
        for i in range(n + 1):
            if i >= 1:
                new_dp[i] += dp[i - 1]
            if i >= 2:
                new_dp[i] += dp[i - 2]
            if i >= 3:
                new_dp[i] += dp[i - 3]
        dp = new_dp
    return dp[n]
```

