def minimum_Length(s):
    left, right = 0, len(s) - 1
    while left < right:
        left_count = s[left:right+1].count(s[left])
        right_count = s[left:right+1].count(s[right])
        if left_count > right_count:
            right -= 1
        else:
            left += 1
    return len(s) - (right - left + 1)
```

```python
def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if s[i - 1] == s[j - 1] and i - j != 0:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[n][n]

