def sort_on_occurence(lst):
    # Create a dictionary to count occurrences of the first element of each tuple
    count_dict = {}
    for item in lst:
        key = item[0]
        if key in count_dict:
            count_dict[key] += 1
        else:
            count_dict[key] = 1

    # Sort the list based on the occurrence of the first element
    sorted_lst = sorted(lst, key=lambda x: count_dict[x[0]])

    # Combine the tuples and count occurrences
    result = []
