        return 1
    if n % 2 == 0:
        even_div = get_max_sum(n // 2)
    else:
        even_div = get_max_sum(n // 2 + 1) + get_max_sum(n // 2)
    if n % 3 == 0:
        three_div = get_max_sum(n // 3)
    else:
        three_div = get_max_sum(n // 3 + 1) + get_max_sum(n // 3)
    if n % 4 == 0:
        four_div = get_max_sum(n // 4)
    else:
        four_div = get_max_sum(n // 4 + 1) + get_max_sum(n // 4)
    if n % 5 == 0:
        five_div = get_max_sum(n // 5)
    else:
        five_div = get_max_sum(n // 5 + 1) + get_max_sum(n // 5)
    return max(n, even_div + three_div + four_div + five_div)
