def newman_prime(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def generate_newman_primes():
        a, b = 1, 1
        while True:
            yield b
            a, b = b, a + b * b

    for i, prime in enumerate(generate_newman_primes(), start=1):
        if i == n:
            return prime
