def tri(n):
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]
    else:
        sequence = [1, 3]
        for i in range(2, n + 1):
            if i % 2 == 0:
                next_value = 1 + i // 2
            else:
                next_value = sequence[i - 1] + sequence[i - 2] + sequence[i]
            sequence.append(next_value)
        return sequence
