def cal_sum(n):
    def perrin(n):
        if n == 0:
            return 3
        elif n == 1:
            return 0
        elif n == 2:
            return 2
        else:
            a, b, c = 3, 0, 2
            for _ in range(3, n + 1):
                a, b, c = b, c, a + b
            return c

    sum_perrin = 0
    for i in range(n + 1):
        sum_perrin += perrin(i)
    return sum_perrin
