def sort_on_occurence(lst):
    # Count the occurrences of the first element of each tuple
    count_dict = {}
    for item in lst:
        key = item[0]
        if key in count_dict:
            count_dict[key] += 1
        else:
            count_dict[key] = 1

    # Sort the list based on the occurrence of the first element
    sorted_lst = sorted(lst, key=lambda x: count_dict[x[0]], reverse=True)

    # Create the output format
    result = []
    for i, item in enumerate(sorted_lst):
        result.append(item + (i + 1,))

    return result
