def get_total_number_of_sequences(n, m):
    if n > m.bit_length():
        return 0
    dp = [1] * (m + 1)
    for _ in range(n - 1):
        new_dp = [0] * (m + 1)
        for i in range(1, m + 1):
            new_dp[i] = sum(dp[j // 2] for j in range(i * 2 - 1, i + 1))
        dp = new_dp
    return sum(dp) - 1
```

```python
def max_sum(arr, n):
    if n == 1:
        return arr[0]

    # Initialize arrays to store the maximum sum ending at each index
    inc = [0] * n
    dec = [0] * n

    inc[0] = arr[0]
    dec[n-1] = arr[n-1]

    # Fill inc[] such that inc[i] stores the maximum sum of increasing subsequence ending with arr[i]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Fill dec[] such that dec[i] stores the maximum sum of decreasing subsequence starting with arr[i]
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # The result will be the maximum value in the sum of inc[] and dec[]
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum
```

