def max_path_sum(triangle, rows, cols):
    if rows == 1:
        return triangle[0][0]
    for i in range(1, rows):
        for j in range(cols):
            if j == 0:
                triangle[i][j] += triangle[i-1][j]
            elif j == cols - 1:
                triangle[i][j] += triangle[i-1][j-1]
            else:
                triangle[i][j] += max(triangle[i-1][j], triangle[i-1][j-1])
    return max(triangle[-1])
```

