import heapq

def func(arr, k):
    count = {}
    for lst in arr:
        for num in lst:
            count[num] = count.get(num, 0) + 1

    heap = []
    for num, freq in count.items():
        heapq.heappush(heap, (freq, num))
        if len(heap) > k:
            heapq.heappop(heap)

    result = []
    while heap:
        result.append(heapq.heappop(heap)[1])
    return result[::-1]
