def magic_square_test(square):
    n = len(square)
    magic_sum = sum(square[0])  # Sum of the first row

    # Check row sums
    for row in square:
        if sum(row) != magic_sum:
            return False

    # Check column sums
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != magic_sum:
            return False

    # Check main diagonal sum
    if sum(square[i][i] for i in range(n)) != magic_sum:
        return False

    # Check secondary diagonal sum
    if sum(square[i][n-1-i] for i in range(n)) != magic_sum:
        return False

    # Check if all numbers are unique
    if len(set(num for row in square for num in row)) != n * n:
        return False

    return True
