from heapq import heappush, heappop

def minPath(grid, k):
	def neighbors(r, c):
		for nr, nc in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
			if 0 <= nr < n and 0 <= nc < n:
				yield nr, nc

	n = len(grid)
	pq = [(grid[0][0], 0, 0)]
	visited = set()
	while k > 0:
		val, r, c = heappop(pq)
		if (r, c) in visited:
			continue
		visited.add((r, c))
		for nr, nc in neighbors(r, c):
			if (nr, nc) not in visited:
				heappush(pq, (grid[nr][nc], nr, nc))
		k -= 1
	return [val] + [grid[r][c] for r, c in visited]
```

