def get_maxgold(grid, n, m):
    def solve(i, j):
        if i == n - 1:
            return grid[i][j]
        if (i, j) in memo:
            return memo[i, j]
        right = solve(i + 1, j)
        down_right = solve(i + 1, j + 1)
        down = solve(i + 1, j - 1)
        memo[i, j] = grid[i][j] + max(right, down_right, down)
        return memo[i, j]

    if not grid or not grid[0]:
        return 0
    memo = {}
    max_gold = 0
    for j in range(m):
        max_gold = max(max_gold, solve(0, j))
    return max_gold
