def max_sub_array_sum_repeated(nums, k, n):
    def kadane_algorithm(arr):
        max_so_far = max_ending_here = arr[0]
        for i in range(1, n):
            max_ending_here = max(arr[i], max_ending_here + arr[i])
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(nums)
    max_kadane = kadane_algorithm(nums)
    max_wrap = total_sum + max_kadane

    if max_wrap > 0:
        return max(max_wrap, max_kadane * k)
    else:
        return max(max_wrap, max_kadane * (k - 1) + total_sum)

