def eulerian_num(n, m):
    if m == 0:
        return 1
    if m == n:
        return (n * (n - 1)) % 1000000007
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[1][1] = 1
    for i in range(2, n + 1):
        dp[i][1] = (dp[i - 1][1] + (i - 1) * dp[i - 1][1]) % 1000000007
        for j in range(2, min(i, m) + 1):
            dp[i][j] = (dp[i - 1][j - 1] + (i - 1) * dp[i - 1][j]) % 1000000007
    return dp[n][m]
```

