def rearange_string(s):
    n = len(s)
    if n < 2:
        return s

    # Count the frequency of each character
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Sort characters by frequency (descending)
    sorted_chars = sorted(freq.keys(), key=lambda x: -freq[x])

    # Create a list to hold the rearranged string
    result = [''] * n

    # Fill odd positions first
    index = 0
    for char in sorted_chars:
        while freq[char] > 0 and index < n:
            result[index] = char
            freq[char] -= 1
            index += 2

    # Fill even positions
    index = 1
    for char in sorted_chars:
        while freq[char] > 0 and index < n:
            result[index] = char
            freq[char] -= 1
            index += 2

    # Check if the rearranged string is valid
    for i in range(1, n):
        if result[i] == result[i - 1]:
            return ''

    return ''.join(result)
