def rearange_string(s):
    n = len(s)
    if n < 2:
        return s

    # Count character frequencies
    freq = [0] * 26
    for char in s:
        freq[ord(char) - ord('a')] += 1

    # Sort characters by frequency
    chars = sorted([(freq[i], chr(i + ord('a'))) for i in range(26)], reverse=True)

    # Create the result string
    result = [''] * n
    even_pos = 0
    odd_pos = 1

    for count, char in chars:
        if even_pos >= n:
            even_pos = 1
            odd_pos = 0

        if count > (n + 1) // 2:
            return ""  # Impossible to rearrange

        for _ in range(count):
            if even_pos < n:
                result[even_pos] = char
                even_pos += 2
            elif odd_pos < n:
                result[odd_pos] = char
                odd_pos += 2

    return ''.join(result)
