def is_num_keith(n):
    # Create a list to store the initial sequence values
    sequence = []
    # Generate the initial sequence values until their sum exceeds n
    num_str = str(n)
    for digit in num_str:
        sequence.append(int(digit))
        if sum(sequence) > n:
            break

    # If the sum of sequence values is already n, n is a Keith number
    if sum(sequence) == n:
        return True

    # Generate the next values in the sequence
    while True:
        next_value = sum(sequence[-len(num_str):])
        sequence.append(next_value)
        if next_value == n:
            return True
        elif next_value > n:
            return False
