    vowels = 'aeiou'
    vowel_map = {'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 's'}
    encoded_message = ''
    for char in message:
        if char.lower() in vowels:
            if char.isupper():
                encoded_message += vowel_map[char.lower()].upper()
            else:
                encoded_message += vowel_map[char.lower()]
        else:
            if char.isupper():
                encoded_message += char.lower()
            else:
                encoded_message += char.upper()
    return encoded_message
```

