def get_maxgold(grid, n, m):
    def dfs(x, y):
        if x == n:
            return 0
        max_gold = 0
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                max_gold = max(max_gold, dfs(nx, ny))
        return grid[x][y] + max_gold

    directions = [(0, 1), (1, 0), (1, 1)]
    max_gold = 0
    for j in range(m):
        max_gold = max(max_gold, dfs(0, j))
    return max_gold
```

