def eulerian_num(n, m):
    if m == 0:
        return 1
    if m == 1:
        return (n-1) * eulerian_num(n-1, m)
    if m == n:
        return eulerian_num(n-1, m-1) * (n-m+1)
    return eulerian_num(n, m-1) * (n-m) + eulerian_num(n, m-1) * (n-m+1)
