def newman_prime(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def next_newman_prime(current):
        candidate = current + 2
        while not is_prime(candidate - 1) or not is_prime((candidate * candidate) + candidate + 1):
            candidate += 2
        return candidate

    current_prime = 2
    for _ in range(n):
        current_prime = next_newman_prime(current_prime)
    return current_prime
```

