def pancake_sort(arr):
    def flip(sub_arr, k):
        sub_arr[:k] = sub_arr[:k][::-1]

    n = len(arr)
    for size in range(n, 1, -1):
        max_index = 0
        for i in range(1, size):
            if arr[i] > arr[max_index]:
                max_index = i
        if max_index != size - 1:
            flip(arr, max_index + 1)
            flip(arr, size)
    return arr
```

