from collections import Counter

def rearange_string(s):
    if len(s) <= 1:
        return s
    char_count = Counter(s)
    max_count_char = char_count.most_common(1)[0]
    if max_count_char[1] > (len(s) + 1) // 2:
        return ""
    result = [''] * len(s)
    even_index = 0
    odd_index = 1
    for char, count in char_count.items():
        while count > 0:
            if even_index < len(s):
                result[even_index] = char
                even_index += 2
                count -= 1
            elif odd_index < len(s):
                result[odd_index] = char
                odd_index += 2
                count -= 1
    return ''.join(result)
