def newman_prime(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def next_newman_prime(current):
        next_num = current + 2
        while True:
            if is_prime(next_num):
                return next_num
            next_num += 2

    current_prime = 2
    for _ in range(n):
        current_prime = next_newman_prime(current_prime)
    return current_prime
