def find_minimum_range(arrays):
    import heapq

    min_heap = []
    max_val = float('-inf')

    for i, arr in enumerate(arrays):
        heapq.heappush(min_heap, (arr[0], i, 0))
        max_val = max(max_val, arr[0])

    start, end = max_val, float('inf')

    while min_heap:
        min_val, arr_idx, elem_idx = heapq.heappop(min_heap)
        if end - start > max_val - min_val:
            start, end = min_val, max_val
        if elem_idx + 1 < len(arrays[arr_idx]):
            next_elem = arrays[arr_idx][elem_idx + 1]
            heapq.heappush(min_heap, (next_elem, arr_idx, elem_idx + 1))
            max_val = max(max_val, next_elem)
            if end - start > max_val - min_heap[0][0]:
                start, end = min_heap[0][0], max_val
        else:
            break

    return start, end
