def max_Product(arr):
    n = len(arr)
    if n < 2:
        return None
    first = second = float('-inf')
    third = fourth = float('inf')
    for x in arr:
        if x > first:
            third, second, first = first, x, second
        elif x > second:
            third, second = second, x
        if x < third:
            third, fourth = x, third
    return (first, second) if first * second > third * fourth else (third, fourth)
```

