def amicable_numbers_sum(n):
    def sum_of_divisors(x):
        return sum([i for i in range(1, x) if x % i == 0])

    amicable_sum = 0
    for num in range(2, n):
        friend = sum_of_divisors(num)
        if friend > num and sum_of_divisors(friend) == num:
            amicable_sum += num + friend
    return amicable_sum // 2
```

