def minimum_Length(s):
    left, right = 0, len(s) - 1
    while left < right:
        left_count = s[left:right+1].count(s[left])
        right_count = s[left:right+1].count(s[right])
        if left_count > right_count:
            right -= 1
        else:
            left += 1
    return len(s) - (right - left + 1)
```

