def rearange_string(s):
    n = len(s)
    if n < 2:
        return s

    count = [0] * 26
    for char in s:
        count[ord(char) - ord('a')] += 1

    first = second = ''
    for i in range(26):
        if count[i] > n // 2:
            return ''
        if count[i] > count[ord(first) - ord('a')]:
            second = first
            first = chr(i + ord('a'))
        elif count[i] > count[ord(second) - ord('a')]:
            second = chr(i + ord('a'))

    if len(first) * 2 > n:
        return ''

    result = [''] * n
    index = 0
    for char in first + second:
        for _ in range(count[ord(char) - ord('a')]):
            if index < n:
                result[index] = char
                index += 2
            else:
                index = 1
                result[index] = char
                index += 2

    return ''.join(result)

assert rearange_string("aab")==('aba')
assert rearange_string("aabb")==('abab')
assert rearange_string("abccdd")==('cdabcd')
