def sort_on_occurence(lst):
    # Count the occurrences of the first element of each tuple
    count_dict = {}
    for item in lst:
        key = item[0]
        if key in count_dict:
            count_dict[key] += 1
        else:
            count_dict[key] = 1

    # Sort the list based on the occurrence of the first element
    sorted_lst = sorted(lst, key=lambda x: count_dict[x[0]])

    # Create the final output format
    result = []
    for item in sorted_lst:
        key = item[0]
        count = count_dict[key]
        if len(item) == 2:
            item += (count,)
        else:
            item = item[:2] + (item[2] + str(count),)
        result.append(item)

    return result
```

