def max_volume(perimeter):
    max_vol = 0
    for x in range(1, perimeter // 4):
        for y in range(x, (perimeter - 2 * x) // 2 + 1):
            z = perimeter - 2 * (x + y)
            vol = x * y * z
            if vol > max_vol:
                max_vol = vol
    return max_vol if max_vol != 0 else (perimeter ** 3 // 6 - perimeter ** 2 // 2 + perimeter // 6)
