def sum_digits_twoparts(n):
    if n <= 10:
        return n
    count = 0
    while n > 0:
        count += n % 10
        n //= 10
    if count == 9:
        return 18
    if count < 9:
        return count + 9 - (9 - count) % 9
    if count > 9:
        return count - (count % 9) + 9
