from typing import List


def remove_duplicates(numbers: List[int]) -> List[int]:
    seen = set()
    duplicates = set()
    result = []

    for num in numbers:
        if num in duplicates:
            continue
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)
            result.append(num)

    return result
